getModels(provider) {
    if (provider !== undefined) {
        const entry = this.providers.get(provider);
        if (!entry)
            return [];
        try {
            return entry.getModels();
        }
        catch {
            return [];
        }
    }
    const models = [];
    for (const entry of this.providers.values()) {
        try {
            models.push(...entry.getModels());
        }
        catch {
            // Best-effort: ill-behaved providers yield no models.
        }
    }
    return models;
}
