            return entry.getAllModels?.() ?? entry.getModels();
        }
        catch {
            return [];
        }
    }
    const models = [];
    for (const entry of this.providers.values()) {
        try {
            models.push(...(entry.getAllModels?.() ?? entry.getModels()));
